// ❌ PITFALL 3: Exception is caught and swallowed — rollback never triggers
@Transactional
public void debitAccount(long accountId, double amount) {
    try {
        accountRepo.debit(accountId, amount);
        auditService.log(accountId); // throws RuntimeException
    } catch (Exception e) {
        log.error("Error", e); // Exception swallowed — transaction COMMITS!
    }
}


